925: fn release_gate(args: Vec<String>) -> Result<(), String> {
926:     let mut production = false;
927:     let mut require_conda = false;
928:     let mut confirmations = BTreeSet::new();
929:     let mut index = 0;
930:     while index < args.len() {
931:         match args[index].as_str() {
932:             "--production" => production = true,
933:             "--require-conda" => require_conda = true,
934:             "--confirm" => {
935:                 index += 1;
936:                 let flag = args
937:                     .get(index)
938:                     .ok_or_else(|| "--confirm requires a value".to_string())?;
939:                 confirmations.insert(flag.clone());
940:             }
941:             other => return Err(format!("unknown release-gate option: {other}")),
942:         }
943:         index += 1;
944:     }
945: 
946:     let mut issues = Vec::new();
947:     check_security_policy(&mut issues);
948:     check_rust_only_files(&mut issues);
949:     check_cargo_metadata(&mut issues);
950:     check_release_version_sync(&mut issues);
951:     check_release_please_config(&mut issues);
952:     check_workflows(&mut issues);
953:     check_no_legacy_surfaces(&mut issues);
954:     if require_conda {
955:         check_conda_recipe(&mut issues);
956:     }
957:     if production {
958:         for flag in CONFIRMATIONS {
959:             if !confirmations.contains(*flag) {
960:                 issues.push(format!("FAIL: external-confirmation-missing: production release requires --confirm {flag}."));
961:             }
962:         }
963:     }
964: 
965:     if issues.is_empty() {
966:         println!("release gate passed");
967:         Ok(())
968:     } else {
969:         for issue in &issues {
970:             eprintln!("{issue}");
971:         }
972:         Err("release gate failed".to_string())
973:     }
974: }
