990: fn check_security_policy(issues: &mut Vec<String>) {
991:     let path = Path::new("SECURITY.md");
992:     let Ok(text) = fs::read_to_string(path) else {
993:         issues.push("FAIL: security-policy-missing: SECURITY.md is required.".to_string());
994:         return;
995:     };
996:     for required in ["Reporting a Vulnerability", "graph_query", "--allow-remote"] {
997:         if !text.contains(required) {
998:             issues.push(format!(
999:                 "FAIL: security-policy-incomplete: SECURITY.md must mention {required:?}."
1000:             ));
1001:         }
1002:     }
