1270: fn check_workflows(issues: &mut Vec<String>) {
1271:     let paths = [
1272:         ".github/workflows/ci.yml",
1273:         ".github/workflows/native.yml",
1274:         ".github/workflows/release.yml",
1275:     ];
1276:     let mut parsed = BTreeMap::new();
1277:     for workflow in paths {
1278:         let Ok(text) = fs::read_to_string(workflow) else {
1279:             issues.push(format!("FAIL: workflow-missing: {workflow} is required."));
1280:             continue;
1281:         };
1282:         let workflow_forbidden = [
1283:             concat!("actions/setup-", "python"),
1284:             concat!("python", " "),
1285:             concat!("p", "ip", " "),
1286:             concat!("py", "test"),
1287:             concat!("ru", "ff"),
1288:             concat!("p", "ip", "-audit"),
1289:             "scripts/",
1290:         ];
1291:         for forbidden in workflow_forbidden {
1292:             if text.contains(forbidden) {
1293:                 issues.push(format!(
1294:                     "FAIL: workflow-python-tooling-present: {workflow} contains {forbidden}."
1295:                 ));
1296:             }
1297:         }
1298:         match yaml_serde::from_str::<YamlValue>(&text) {
1299:             Ok(value) => {
1300:                 parsed.insert(workflow, value);
1301:             }
1302:             Err(error) => issues.push(format!(
1303:                 "FAIL: workflow-yaml-invalid: {workflow} is not valid YAML: {error}."
1304:             )),
1305:         }
1306:     }
1307:     if let (Some(ci), Some(native), Some(release)) = (
1308:         parsed.get(".github/workflows/ci.yml"),
1309:         parsed.get(".github/workflows/native.yml"),
1310:         parsed.get(".github/workflows/release.yml"),
1311:     ) {
1312:         check_workflow_policy(ci, native, release, issues);
1313:     }
1314: }
